package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenCompareTest {
 @Test public void normalGradeSevenSupplyIncludesOfficialRangeAndAllThreeRelations(){String pack="na-nied-primary-2024-v1",id="el_compare_10000";assertTrue(GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(pack)).findFirst().orElseThrow().inGrade(id,7));var limits=GlobalCurriculum.limits(pack,id,7);assertEquals(1000000,limits.wholeMaximum(-1));assertEquals(0,limits.givenMinimum(-1));Generator g=new Generator(new Random(301));Set<String> signs=new HashSet<>();List<String> recent=new ArrayList<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var f=WholeCompareRelations.frames(q);assertFalse(f.isEmpty());int a=Integer.parseInt(f.get(0).expected()),b=Integer.parseInt(f.get(1).expected());assertTrue(a>=0&&a<=1000000&&b>=0&&b<=1000000);signs.add(f.get(f.size()-1).expected());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of("<","=",">"),signs);}
 @Test public void boundaryComparisonAndHelpUsePublicGivens(){Checker c=new Checker();for(int[] pair:new int[][]{{0,1000000},{1000000,0},{1000000,1000000},{0,0},{999999,1000000},{1000000,999999},{100005,100050}}){String correct=pair[0]<pair[1]?"<":pair[0]>pair[1]?">":"=";Question q=new Question("el_compare_10000",pair[0]+"  □  "+pair[1],"poison","poison");assertTrue(c.check(q,List.of(),List.of(correct)).correct());for(String wrong:Set.of("<","=",">"))if(!wrong.equals(correct))assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(wrong)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1")).status);var frames=WholeCompareRelations.frames(q);assertEquals(correct,frames.get(frames.size()-1).expected());WholeCompareRelations.attach(q);assertFalse(HelpPlan.forQuestion(q).canTransfer());}}
}
